import Foundation

/// The static content of the demo: users, groups, memberships, challenges and the shape
/// of the seeded history. Everything else is generated by `DemoStore`.
enum DemoSeed {
    static let currentUserID = "demo-user-me"

    static let warriorsID = "demo-group-warriors"
    static let flatmatesID = "demo-group-flatmates"
    static let sundayID = "demo-group-sunday"

    static let users: [User] = [
        User(id: currentUserID, displayName: "Alex", avatarEmoji: "🦊"),
        User(id: "demo-user-sam", displayName: "Sam", avatarEmoji: "🐻"),
        User(id: "demo-user-jo", displayName: "Jo", avatarEmoji: "🐢"),
        User(id: "demo-user-mika", displayName: "Mika", avatarEmoji: "🐙"),
        User(id: "demo-user-lee", displayName: "Lee", avatarEmoji: "🐧")
    ]

    static let groups: [Group] = [
        Group(
            id: warriorsID,
            name: "Weekend Warriors",
            inviteCode: "K7M2PQ",
            challengesPerWeek: 5,
            theme: "Outdoors only",
            language: "en",
            timezone: TimeZone.current.identifier,
            ownerId: currentUserID,
            memberCount: 5
        ),
        Group(
            id: flatmatesID,
            name: "Flatmates",
            inviteCode: "H3NDQ8",
            challengesPerWeek: 3,
            theme: "Indoors only",
            language: "en",
            timezone: TimeZone.current.identifier,
            ownerId: "demo-user-sam",
            memberCount: 3
        ),
        Group(
            id: sundayID,
            name: "Sunday Club",
            inviteCode: "PL4XZ9",
            challengesPerWeek: 5,
            theme: "Long walks",
            language: "en",
            timezone: TimeZone.current.identifier,
            ownerId: "demo-user-mika",
            memberCount: 3
        )
    ]

    /// The members of every seeded group.
    static let membership: [String: [String]] = [
        warriorsID: [currentUserID, "demo-user-sam", "demo-user-jo", "demo-user-mika", "demo-user-lee"],
        flatmatesID: ["demo-user-sam", "demo-user-jo", currentUserID],
        sundayID: ["demo-user-mika", "demo-user-lee", "demo-user-jo"]
    ]

    /// The challenges of the current week.
    static func currentTitles(for groupID: String) -> [String] {
        switch groupID {
        case flatmatesID:
            return ["No-phone afternoon", "Letter to a stranger", "Cook a stranger's recipe"]
        default:
            return [
                "Sunrise on a hill",
                "Cook a stranger's recipe",
                "No-phone afternoon",
                "Sunset swim",
                "Letter to a stranger"
            ]
        }
    }

    /// Every challenge title the demo can use for older weeks and for new groups.
    static let challengePool: [String] = [
        "Sunrise on a hill",
        "Cook a stranger's recipe",
        "No-phone afternoon",
        "Sunset swim",
        "Letter to a stranger",
        "Walk 10k without music",
        "Send a postcard",
        "Cook a dish you never made",
        "Photograph every colour of the rainbow",
        "Swap a book with a stranger",
        "Wake up before sunrise",
        "Do 30 minutes of yoga",
        "Cook a meal for a neighbour",
        "Learn a word in another language",
        "Ride a bike for 20 minutes"
    ]

    /// One seeded week of history: who finished a challenge and who did not.
    struct HistoryEntry: Sendable {
        let accept: [String]
        let reject: [String]
    }

    static func history(for groupID: String) -> [HistoryEntry] {
        switch groupID {
        case flatmatesID:
            return [
                HistoryEntry(accept: ["demo-user-sam", "demo-user-jo"], reject: []),
                HistoryEntry(accept: ["demo-user-sam", currentUserID], reject: ["demo-user-jo"])
            ]
        case sundayID:
            return [
                HistoryEntry(accept: ["demo-user-mika", "demo-user-lee"], reject: ["demo-user-jo"])
            ]
        default:
            return [
                HistoryEntry(accept: [currentUserID, "demo-user-sam"], reject: ["demo-user-jo"]),
                HistoryEntry(accept: [currentUserID, "demo-user-sam", "demo-user-jo"], reject: ["demo-user-mika"]),
                HistoryEntry(
                    accept: [currentUserID, "demo-user-sam", "demo-user-jo", "demo-user-mika"],
                    reject: ["demo-user-lee"]
                )
            ]
        }
    }

    static func description(for title: String, difficulty: Difficulty) -> String {
        switch difficulty {
        case .easy:
            return "“\(title)” should take you less than an hour. A photo or a short video is enough."
        case .medium:
            return "“\(title)” needs a bit of planning, but it is doable before Sunday night."
        case .hard:
            return "“\(title)” is the big one of the week. Take your time and make it count."
        }
    }
}
